// @ts-nocheck
/* eslint-disable */
/**
 * Sales-document form engine — ob. GENERATED by tools/sync-sales-doc-form.mjs from web/pages/sales_doc_ob_form.xhtml + its components — do not edit; change the script and run `npm run sales-doc-form:sync`.
 *
 * The page script(s) of the Java form, same behaviour line by line, on top of the engine scripts of sales-doc-libs.engine.ts (the scripts
 * its head loads: sales_doc_preview.js · sales_doc_print.js · sales_doc_saved.js · sales_doc_finance.js · sales_doc_validate.js · sales_doc_customer.js · sales_doc_pager.js · sales_doc_search.js · sales_doc_ref.js · sales_doc_items.js · sales_doc_attach.js · sales_doc_modal.js · sales_doc_pay_modal.js).
 *
 * WHY it is imperative DOM code and not Angular components: the Java page draws its HTML from data as strings. Porting it 1:1 is what
 * guarantees the screen, texts and states are identical to the production system.
 * "@ts-nocheck": the source is ES5 written for a browser global scope; typing it would change it, not port it.
 *
 * What changed versus the Java file (all of it lives in tools/sync-sales-doc-form.mjs):
 *   - the environment is injected (SalesDocFormEnv): messages, fetch (the BFF contract of sales-doc-backend.ts), SweetAlert, navigation, the
 *     context path — in Java these were EL, the URL and globals;
 *   - the strip of tabs that sales_doc_tabs.xhtml injects into the Java top bar is drawn by the Angular shell (nav.config.ts);
 *   - global listeners and timers added through listen() / tmo(), the animation frames, the boxes the scripts move to <body> and the response
 *     guard are removed by the function returned from startSalesDocOb().
 */

import { createSalesDocLibs, createSalesDocRuntime } from './sales-doc-libs.engine';

export interface SalesDocFormEnv {
  /** commonBean.msg['key'] in the active language */
  t: (key: string) => string;
  /** the BFF contract of the page: /board/prospect-list, /rvapi?action=materials, /board/prospect/attachments, /board/chat-master-data (see sales-doc-backend.ts) */
  fetch: (input: string, init?: RequestInit) => Promise<Response>;
  /** SweetAlert v2 (js/sweetalert/sweetalertv1.min.js) */
  swal: (options: Record<string, unknown>) => Promise<any>;
  /** window.location.href = … : a route of this app, or an absolute address of this origin (the link back to the list) */
  navigate: (address: string) => void;
  /** #{request.contextPath}: where the BFF is ("" here) */
  ctx: string;
}

export function startSalesDocOb(env: SalesDocFormEnv): () => void {
  var destroyed = false;
  var disposers = [];
  var timers = [];
  var observers = [];
  function listen(target, type, fn, opts) {
    target.addEventListener(type, fn, opts);
    disposers.push(function () { target.removeEventListener(type, fn, opts); });
  }
  function tmo(fn, ms) { var h = setTimeout(function () { if (!destroyed) { fn(); } }, ms); timers.push(h); return h; }
  function track(o) { observers.push(o); return o; }
  /* document.readyState / DOMContentLoaded / load of the page the script was written for (see the generator) */
  var readyState = 'loading';
  var readyQueue = [];
  var loadQueue = [];
  function onReady(fn) { if (readyState === 'loading') { readyQueue.push(fn); } else { tmo(fn, 0); } }
  function onLoad(fn) { if (readyState !== 'complete') { loadQueue.push(fn); } else { tmo(fn, 0); } }
  function runQueue(queue, type) {
    queue.splice(0).forEach(function (fn) {
      try { fn.call(type === 'load' ? window : document, new Event(type)); } catch (e) { console.error(e); }
    });
  }

  /* Nothing that is still in flight when the screen is left may repaint it: after destroy() a request never settles. */
  var rawFetch = env.fetch;
  var never = function () { return new Promise(function () {}); };
  var guardResponse = function (r) {
    return {
      ok: r.ok, status: r.status, statusText: r.statusText, headers: r.headers, url: r.url,
      clone: function () { return guardResponse(r.clone()); },
      json: function () { return r.json().then(function (v) { return destroyed ? never() : v; }); },
      text: function () { return r.text().then(function (v) { return destroyed ? never() : v; }); },
      blob: function () { return r.blob().then(function (v) { return destroyed ? never() : v; }); },
      arrayBuffer: function () { return r.arrayBuffer().then(function (v) { return destroyed ? never() : v; }); }
    };
  };
  env = Object.assign({}, env, {
    fetch: function (a, b) {
      if (destroyed) { return never(); }
      return rawFetch(a, b).then(
        function (r) { return destroyed ? never() : guardResponse(r); },
        function (e) { return destroyed ? never() : Promise.reject(e); });
    }
  });
  var rt = createSalesDocRuntime({ listen: listen, tmo: tmo, track: track });
  /* the engine scripts the head of the Java page loads, in its order */
  createSalesDocLibs(env, rt, ["preview","print","saved","finance","validate","customer","pager","search","ref","items","attach","modal","pay_modal"]);


  /* ---- inline script 1 of 1 of the page ---- */
  (function () {
                  var MSG = {
                      pickProduct: env.t("label.qt.pick_product"),
                      needWarehouse: env.t("label.ob.warehouse_pick"),
                      removeItem: env.t("label.qt.remove_item"),
                      alertTitle: env.t("label.ld2.alert_title"),
                      needCustomer: env.t("label.qt.validate_customer"),
                      needItems: env.t("label.qt.validate_items"),
                      colQty: env.t("label.qt.col_qty"),
                      colPrice: env.t("label.qt.col_price"),
                      colDisc: env.t("label.qt.discount"),
                      colRemark: env.t("label.it.col_remark"),
                      docTitle: env.t("label.sales_doc_tab.delivery"),
                      notSaved: env.t("label.ob.not_saved"),
                      removePayRow: env.t("label.bk.remove_pay_row")
                  };
                  function g(id) { return document.getElementById(id); }
                  /* ยอดรวมล่าสุดจากตารางรายการ (SalesDocItems) — ใช้คำนวณการ์ดสรุปยอด/ไฟแนนซ์ */
                  var totals = { grand: 0, itemsGross: 0, discountTotal: 0 };

                  /* ---------- ตัวเลข ---------- */
                  function parseNum(v) {
                      var n = parseFloat(String(v == null ? '' : v).replace(/,/g, ''));
                      return isFinite(n) ? n : 0;
                  }
                  function round2(n) { return Math.round((n + Number.EPSILON) * 100) / 100; }
                  function fmt(n) { return round2(n).toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 }); }
                  function fmtQty(n) { return round2(n).toLocaleString('en-US', { maximumFractionDigits: 2 }); }

                  /* ---------- ตัวช่วย ---------- */
                  function esc(s) { return String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/"/g, '&quot;').replace(/</g, '&lt;'); }
                  function rowField(tr, f) { return tr.querySelector('[data-f="' + f + '"]'); }

                  /* ---------- สรุปยอดเงินจอง ---------- */
                  /* ★ 29/09: เหมือนฟอร์มใบจอง (sales_doc_bk_form.xhtml) ทุกประการ — สูตรอนุมานจากลำดับ หัก/บวก ในภาพ
                     ช่องที่ยังไม่มี rule จริงจาก backend ตรึงไว้ที่ 0 เสมอ มีแค่ "เงินจอง" ที่กรอกได้ */
                  function obCalcSummary() {
                      /* ราคาขายสุทธิรวม VAT = รวมทั้งสิ้นของแถบสรุปยอดรวม (หลังส่วนลดแถว+ส่วนลดเพิ่มเติม) */
                      var itemsNetTotal = totals.grand;
                      if (finance) { finance.recalc(totals.itemsGross, totals.discountTotal); }
                      var financeAmount = parseNum(g('obFinanceAmount').textContent);
                      var downPayment = round2(Math.max(0, itemsNetTotal - financeAmount));
                      var bookingDeposit = parseNum(g('obBookingDeposit').value);
                      var downPaymentDiscount = parseNum(g('obDownPaymentDiscount').textContent);
                      var markupDiscount = parseNum(g('obMarkupDiscount').textContent);
                      var finalBillDiscount = parseNum(g('obFinalBillDiscount').textContent);
                      var tradeInAmount = parseNum(g('obTradeInAmount').value);
                      var otherIncome = parseNum(g('obOtherIncome').textContent);
                      var remaining = round2(downPayment - bookingDeposit - downPaymentDiscount - markupDiscount - finalBillDiscount - tradeInAmount + otherIncome);
                      var reimburseExpense = parseNum(g('obReimburseExpense').textContent);
                      var grandTotalNet = round2(remaining + reimburseExpense);

                      g('obNetPriceTotal').textContent = fmt(itemsNetTotal);
                      g('obFinanceAmount').textContent = fmt(financeAmount);
                      g('obDownPayment').textContent = fmt(downPayment);
                      g('obDownPaymentDiscount').textContent = fmt(downPaymentDiscount);
                      g('obMarkupDiscount').textContent = fmt(markupDiscount);
                      g('obFinalBillDiscount').textContent = fmt(finalBillDiscount);
                      g('obOtherIncome').textContent = fmt(otherIncome);
                      g('obRemaining').textContent = fmt(remaining);
                      g('obReimburseExpense').textContent = fmt(reimburseExpense);
                      g('obGrandTotalNet').textContent = fmt(grandTotalNet);

                      g('obDepositDue').textContent = fmt(finance && finance.isFinance() ? finance.netPayable() : grandTotalNet);
                      obCalcPayment();
                  }

                  /* ---------- รูปแบบขาย "ไฟแนนซ์" (★ 30/09) — ตรรกะกลางอยู่ที่ resources/support/sales_doc_finance.js ---------- */
                  var finance = SalesDocFinance.init({
                      prefix: 'obf',
                      saleTypeId: 'obSaleType',
                      hideIds: ['obSummaryRow', 'obSummaryCard'],
                      soloGridId: 'obCheckoutGrid',
                      onChange: obCalcSummary
                  });

                  /* ---------- ตารางรายการสินค้า (เลือกสินค้าจาก master-data/materials) + แถบสรุปยอดรวม — ตรรกะกลาง resources/support/sales_doc_items.js (★ 09/10 ใช้ร่วมกับใบจอง) ---------- */
                  /* ★ 19/10 (มาตรฐานการกรอกข้อมูลและการแจ้งเตือน — ใช้กับทุกเอกสาร): resources/support/sales_doc_validate.js — ผูกก่อนสร้างส่วนต่างๆ */
                  var VAL = window.SalesDocValidate;
                  VAL.bind();
                  var items = SalesDocItems.init({
                      prefix: 'ob',
                      ctx: env.ctx,
                      strict: true,
                      msg: { removeItem: MSG.removeItem, pickProduct: MSG.pickProduct, colQty: MSG.colQty, colPrice: MSG.colPrice, colDisc: MSG.colDisc, colRemark: MSG.colRemark },
                      onChange: function (t) { totals = t; obCalcSummary(); }
                  });

                  /* ---------- การชำระเงิน ---------- */
                  var payRowsBody = g('obPayRows');
                  function obCalcPayment() {
                      var due = parseNum(g('obDepositDue').textContent);
                      var entered = 0;
                      Array.prototype.forEach.call(payRowsBody.rows, function (tr) {
                          entered += parseNum(rowField(tr, 'amount').value);
                      });
                      entered = round2(entered);
                      var outstanding = round2(Math.max(0, due - entered));
                      g('obNetPayment').textContent = fmt(entered);
                      g('obOutstanding').textContent = fmt(outstanding);
                      g('obOutstanding').classList.toggle('bk-zero', outstanding === 0);
                      g('obChange').textContent = fmt(round2(Math.max(0, entered - due)));
                      g('obPayProgress').style.width = (due > 0 ? Math.min(100, entered / due * 100) : 0) + '%';
                  }
                  function addPayRow(methodLabel) {
                      var tr = document.createElement('tr');
                      tr.innerHTML =
                          '<td><input type="text" class="qm-cell" data-f="code" maxlength="30" data-vf="TXT-CODE" data-max="30" data-allow-special="true"/></td>' +
                          '<td class="bk-pay-method-name">' + esc(methodLabel) + '</td>' +
                          '<td><input type="text" class="qm-cell qm-r" data-f="amount" inputmode="decimal" value="0.00" data-vf="NUM-DEC2" data-allow-special="true"/></td>' +
                          '<td class="qt-no-print qm-c"><button type="button" class="qm-icon-btn qt-del" title="' + esc(MSG.removePayRow) + '" aria-label="' + esc(MSG.removePayRow) + '"><i class="fas fa-trash-alt"></i></button></td>';
                      payRowsBody.appendChild(tr);
                      wireMoney(rowField(tr, 'amount'), obCalcPayment);
                      obCalcPayment();
                      return tr;
                  }
                  payRowsBody.addEventListener('input', function (e) {
                      if (e.target.getAttribute('data-f') === 'amount') { obCalcPayment(); }
                  });
                  payRowsBody.addEventListener('click', function (e) {
                      var del = e.target.closest && e.target.closest('.qt-del');
                      if (!del) { return; }
                      del.closest('tr').remove();
                      obCalcPayment();
                  });
                  /* ---------- modal ชำระเงินแต่ละวิธี (mock) — ตรรกะกลางอยู่ที่ resources/support/sales_doc_pay_modal.js ใช้ร่วมใบจอง/ใบส่งสินค้า (★ 06/10) ---------- */
                  SalesDocPayModal.init({
                      prefix: 'ob',
                      msg: {
                          alertTitle: MSG.alertTitle,
                          amount: env.t("label.bk.pm_amount"), bank: env.t("label.bk.pm_bank"),
                          cardNo: env.t("label.bk.pm_card_no"), approval: env.t("label.bk.pm_approval"),
                          refNo: env.t("label.bk.pm_ref_no"), date: env.t("label.bk.pm_date"),
                          chequeNo: env.t("label.bk.pm_cheque_no"), chequeDate: env.t("label.bk.pm_cheque_date"),
                          received: env.t("label.bk.pm_received"), giftNo: env.t("label.bk.pm_giftcard_no"),
                          points: env.t("label.bk.pm_points_used"), desc: env.t("label.bk.pm_other_desc"),
                          needAmount: env.t("label.bk.pm_need_amount")
                      },
                      parseNum: parseNum,
                      fmt: fmt,
                      /* ยอดเริ่มต้นในช่องจำนวนเงิน = ยอดที่ต้องชำระ - ที่กรอกไปแล้ว */
                      remaining: function () { return round2(Math.max(0, parseNum(g('obDepositDue').textContent) - parseNum(g('obNetPayment').textContent))); },
                      addPayment: function (methodLabel, code, amount) {
                          var tr = addPayRow(methodLabel);
                          rowField(tr, 'code').value = code;
                          rowField(tr, 'amount').value = fmt(amount);
                          obCalcPayment();
                      }
                  });

                  function wireMoney(el, onChange) {
                      onChange = onChange || function () {};
                      el.addEventListener('focusout', function () { if (!el.classList.contains('qm-invalid')) { el.value = fmt(parseNum(el.value)); } onChange(); });   /* ผิดรูปแบบ (sales_doc_validate.js) = คงค่าไว้ให้เห็นพร้อมข้อความใต้ช่อง */
                      el.addEventListener('focusin', function () { el.value = String(parseNum(el.value) || ''); el.select(); });
                  }
                  wireMoney(g('obBookingDeposit'), obCalcSummary);
                  g('obBookingDeposit').addEventListener('input', obCalcSummary);
                  /* ---------- ยอดจากราคารถยนต์เก่า + modal "คู่ค้า" (★ 30/09) ---------- */
                  /* ช่องยอดเป็น input กรอกเองได้ (เดิมเป็นตัวเลขอ่านอย่างเดียว): จัดรูปแบบตอนออกจากช่อง / คำนวณสดตอนพิมพ์ */
                  wireMoney(g('obTradeInAmount'), obCalcSummary);
                  g('obTradeInAmount').addEventListener('input', obCalcSummary);

                  /* แหล่งข้อมูลคู่ค้า — ยังไม่มี API รายชื่อคู่ค้า (business partner) จึงว่างไว้: เมื่อมี endpoint ให้แทนที่ด้วยการโหลดจริง
                     รูปแบบแถว { code: 'BP-006', name: 'บริษัท ...' } ; ปุ่ม Refresh เรียก loadPartners() ใหม่ */
                  var PARTNER_PAGE_SIZE = 5;
                  var partners = [];
                  var partnerPage = 1;
                  var selectedPartner = null;
                  var partnerModal = SalesDocModal.make('obPt');
                  function loadPartners() { partners = []; }
                  function partnerMatches() {
                      var q = g('obPtSearch').value.trim().toLowerCase();
                      return partners.filter(function (p) { return !q || (p.code + ' ' + p.name).toLowerCase().indexOf(q) !== -1; });
                  }
                  function renderPartners() {
                      var list = partnerMatches();
                      var pages = Math.max(1, Math.ceil(list.length / PARTNER_PAGE_SIZE));
                      partnerPage = Math.min(Math.max(1, partnerPage), pages);
                      var rows = g('obPtRows');
                      if (!list.length) {
                          rows.innerHTML = '<tr class="bk-oi-empty"><td colspan="2">' + esc(env.t("label.sd.no_records_found")) + '</td></tr>';
                      } else {
                          rows.innerHTML = list.slice((partnerPage - 1) * PARTNER_PAGE_SIZE, partnerPage * PARTNER_PAGE_SIZE).map(function (p) {
                              var sel = selectedPartner && selectedPartner.code === p.code ? ' class="bk-pt-selected"' : '';
                              return '<tr data-code="' + esc(p.code) + '"' + sel + '><td class="bk-pt-col-code">' + esc(p.code) + '</td><td>' + esc(p.name) + '</td></tr>';
                          }).join('');
                      }
                      var pager = '<button type="button" data-pg="1"><i class="fas fa-angle-double-left"></i></button>' +
                          '<button type="button" data-pg="' + (partnerPage - 1) + '"><i class="fas fa-angle-left"></i></button>' +
                          '<button type="button" class="bk-pt-page-cur" data-pg="' + partnerPage + '">' + partnerPage + '</button>' +
                          '<button type="button" data-pg="' + (partnerPage + 1) + '"><i class="fas fa-angle-right"></i></button>' +
                          '<button type="button" data-pg="' + pages + '"><i class="fas fa-angle-double-right"></i></button>';
                      g('obPtPager').innerHTML = pager;
                      rt.raf(partnerModal.center);
                  }
                  g('obBtnTradeInPartner').addEventListener('click', function () {
                      partnerPage = 1;
                      renderPartners();
                      partnerModal.show();
                      g('obPtSearch').focus();
                  });
                  g('obPtSearch').addEventListener('input', function () { partnerPage = 1; renderPartners(); });
                  g('obPtRefresh').addEventListener('click', function () { loadPartners(); g('obPtSearch').value = ''; partnerPage = 1; renderPartners(); });
                  g('obPtPager').addEventListener('click', function (e) {
                      var b = e.target.closest && e.target.closest('button[data-pg]');
                      if (!b) { return; }
                      partnerPage = parseInt(b.getAttribute('data-pg'), 10) || 1;
                      renderPartners();
                  });
                  g('obPtRows').addEventListener('click', function (e) {
                      var tr = e.target.closest && e.target.closest('tr[data-code]');
                      if (!tr) { return; }
                      var code = tr.getAttribute('data-code');
                      selectedPartner = partners.filter(function (p) { return p.code === code; })[0] || null;
                      renderPartners();
                  });
                  g('obPtSelect').addEventListener('click', function () {
                      if (!selectedPartner) { return; }
                      g('obTradeInPartnerName').textContent = selectedPartner.code + ' ' + selectedPartner.name;
                      partnerModal.hide();
                  });
                  loadPartners();


                  var HAS_FIELD_SIZING = !!(window.CSS && CSS.supports && CSS.supports('field-sizing', 'content'));
                  function autoGrow(ta) {
                      if (HAS_FIELD_SIZING) { return; }
                      ta.style.height = 'auto';
                      ta.style.height = ta.scrollHeight + 'px';
                  }
                  Array.prototype.forEach.call(document.querySelectorAll('.qt-paper textarea'), function (ta) {
                      ta.addEventListener('input', function () { autoGrow(ta); });
                  });

                  /* ---------- ลูกค้า (ส่วน B) + pop-up ค้นหา/แก้ไข — ตรรกะกลางอยู่ที่ resources/support/sales_doc_customer.js ใช้ร่วม ใบเสนอราคา/ใบจอง/ใบส่งสินค้า (★ 06/10) ---------- */
                  var CUST_MSG = {
                      changeCustomer: env.t("label.qt.change_customer"),
                      searchCustomer: env.t("label.ld2.search_customer"),
                      editCustomer: env.t("label.qt.edit_customer"),
                      createCustomer: env.t("label.qt.create_customer"),
                      createAndPick: env.t("label.qt.create_and_pick"),
                      saveEdit: env.t("label.qt.save_edit"),
                      countryTh: env.t("label.qt.country_th"),
                      pick: env.t("label.qt.pick"),
                      noResult: env.t("label.qt.no_result"),
                      searchFailed: env.t("label.qt.search_failed"),
                      loading: env.t("label.qt.loading_search"),
                      fillRequired: env.t("label.qt.fill_required"),
                      taxId13: env.t("label.qt.taxid_13"),
                      lblName: env.t("label.qt.cust_name"),
                      lblTaxId: env.t("label.qt.tax_id_ph"),
                      lblAddr: env.t("label.qt.cust_contract_addr")
                  };
                  var cust = SalesDocCustomer.init({
                      prefix: 'ob',
                      ctx: env.ctx,
                      msg: CUST_MSG,
                      onChange: function (c) {
                          g('obPartySaleTeam').value = c.team || '';
                          var host = g('obCName') ? g('obCName').closest('.qm-cus-nameline') || g('obCName') : null;
                          if (c && c.code != null && host) { VAL.clear(host); }   /* เลือกลูกค้าแล้ว — ล้างข้อความ "กรุณาเลือกลูกค้า" */
                      }
                  });
                  function warn(text) { env.swal({ title: MSG.alertTitle, text: text, icon: 'warning', timer: 3000, buttons: false }); }

                  /* ---------- เอกสารแนบ — อัปโหลดจริงเหมือนหน้า Lead (ไฟล์แนบกับทะเบียนลูกค้าที่เลือกในเอกสาร) — resources/support/sales_doc_attach.js ---------- */
                  SalesDocAttach.init({
                      prefix: 'ob',
                      ctx: env.ctx,
                      strict: true,
                      getProspectId: function () { var c = cust.get(); return c && c.id ? c.id : null; }
                  });

                  /* ---------- ปุ่ม ---------- */
                  /* ★ 15/10: ตัวอย่างเอกสารหลังกดบันทึก (ปุ่มพิมพ์ / PDF อยู่ในหน้าต่างตัวอย่าง) */
                  var saved = SalesDocSaved.init({
                      prefix: 'ob',
                      paper: g('obPaper'),
                      docPrefix: 'OB',
                      kind: 'formal',
                      listUrl: document.querySelector('.qt-back').href,
                      docNoField: 'obDocNo'
                  });
                  /* ★ 12/10: pop-up "ค้นหาเอกสาร" (resources/support/sales_doc_search.js) — เปิดจากปุ่มที่หัวส่วน C ; ปุ่ม "ค้นหาเอกสาร" เดิมบนแถบปุ่มบนถอดออกแล้วตามที่ user สั่ง (ซ้ำกับปุ่มที่หัวส่วน C)
                     ยังไม่มี API ค้นใบส่งสินค้าฝั่ง backend → ยังไม่ส่ง search/onPick = ตารางใน pop-up แจ้งว่ายังไม่เชื่อมต่อ (ไม่ใช้ข้อมูลสมมติ) */
                  SalesDocSearch.init({ prefix: 'ob' });
                  /* ★ 14/10: อ้างอิงใบจอง/ใบเสนอราคา (ไม่บังคับ) — เติมลูกค้า/รายการสินค้า/VAT/ส่วนลดเพิ่มเติม (resources/support/sales_doc_ref.js)
                     + เฉพาะหน้านี้: รูปแบบขายตามเอกสารต้นทาง, อ้างอิงใบจอง → เงินจองที่รับแล้วไปเป็น "หัก เงินจอง" (อ้างอิงใบเสนอราคาไม่แตะช่องนี้ เพราะไม่มีเงินจอง) */
                  SalesDocRef.init({
                      prefix: 'ob',
                      kinds: ['bk', 'qt'],
                      customer: cust,
                      items: items,
                      onApply: function (doc, kind) {
                          var saleType = g('obSaleType');
                          var knownSaleType = Array.prototype.some.call(saleType.options, function (opt) { return opt.value === doc.saleType; });
                          if (knownSaleType) {
                              saleType.value = doc.saleType;
                              saleType.dispatchEvent(new Event('change', { bubbles: true }));
                          }
                          if (kind === 'bk' && doc.bookingDeposit != null) { g('obBookingDeposit').value = fmt(parseNum(doc.bookingDeposit)); }
                          obCalcSummary();
                      }
                  });
                  /* บันทึก — ★ 12/10: ปุ่มบนแถบปุ่มบน (obSaveTopBtn เหมือนใบจอง) + ปุ่มเดิมท้ายส่วนชำระเงิน (obSaveBtn ในแถบ .bk-checkout-foot) ใช้การตรวจชุดเดียวกัน */
                  /* ★ 19/10 (มาตรฐานฯ G3/G4/A3): ตรวจทุกช่องพร้อมกัน — ช่องที่มี data-vf/data-req ใน obPaper + คลัง → ลูกค้า (มีเลขภาษี/ที่อยู่) → สินค้า ;
                     ไม่ผ่าน = แถบแดง "ยังบันทึกไม่ได้: ..." ครบทุกข้อ + เลื่อนไปช่องแรก */
                  function custHost() { return g('obCName') ? g('obCName').closest('.qm-cus-nameline') || g('obCName') : null; }
                  /* คลัง (บังคับตามสเปก): ยังไม่มี master data คลังสินค้า → dropdown มีแต่ตัวเลือกว่าง จึงตรวจเฉพาะเมื่อมีรายการให้เลือก */
                  function checkWarehouse() { var wh = g('obDocWh'); return VAL.flag(wh, wh.options.length > 1 && !wh.value ? MSG.needWarehouse : ''); }
                  function checkCustomer() {
                      var selected = cust.get();
                      if (!selected) { return VAL.flag(custHost(), MSG.needCustomer); }
                      var miss = [];
                      if (!selected.taxId) { miss.push(CUST_MSG.lblTaxId); }
                      if (!selected.addr) { miss.push(CUST_MSG.lblAddr); }
                      return VAL.flag(custHost(), miss.length ? CUST_MSG.fillRequired + ' ' + miss.join(', ') : '');
                  }
                  function checkItems() { return items.hasItem() ? VAL.flag(g('obAddRow'), '') : VAL.flag(g('obAddRow'), MSG.needItems); }
                  function saveDoc() {
                      if (!VAL.validateDocument(g('obPaper'), [checkWarehouse, checkCustomer, checkItems])) { return; }
                      /* ★ 19/10: ยังไม่มี API บันทึกใบส่งสินค้า → pop-up ใช้เลขที่ชั่วคราว + แถบแจ้งว่ายังไม่ได้บันทึกเข้าระบบ (มี API แล้ว: saved.open({ docNo, persisted: true }) ; API ตอบไม่สำเร็จ = VAL.systemError(ข้อความจากระบบ) แถบ A7) */
                      saved.open({ persisted: false });
                  }
                  ['obSaveTopBtn', 'obSaveBtn'].forEach(function (id) {
                      var saveBtn = g(id);
                      if (saveBtn) { saveBtn.addEventListener('click', saveDoc); }
                  });
                  /* บันทึกร่าง — ยังไม่ผ่านการตรวจครบเหมือนปุ่มบันทึกจริง (ร่างไม่บังคับกรอกครบ) */
                  var saveDraftBtn = g('obSaveDraftBtn');
                  if (saveDraftBtn) {
                      saveDraftBtn.addEventListener('click', function () {
                          env.swal({ title: MSG.docTitle, text: MSG.notSaved, icon: 'info' });
                      });
                  }
                  /* ปุ่มลัดสรุปยอด (คืนรายการ/รายได้อื่น/ค่าใช้จ่าย/โปรโมชั่น/เติมสะสม) — ยังไม่มี modal/backend จริงเบื้องหลัง
                     ★ 14/10: ปุ่มที่ย้ายไปข้างแถวมีข้อความสั้น ("เพิ่ม") → หัว pop-up ใช้ data-title แทนข้อความบนปุ่ม */
                  Array.prototype.forEach.call(document.querySelectorAll('.bk-sum-act'), function (btn) {
                      btn.addEventListener('click', function () {
                          env.swal({ title: btn.getAttribute('data-title') || btn.textContent.trim(), text: MSG.notSaved, icon: 'info', timer: 3000, buttons: false });
                      });
                  });

                  /* ---------- ค่าเริ่มต้น ---------- */
                  var todayD = new Date();
                  var pad2 = function (n) { return String(n).padStart(2, '0'); };
                  var todayStr = todayD.getFullYear() + '-' + pad2(todayD.getMonth() + 1) + '-' + pad2(todayD.getDate());
                  /* วันที่เอกสาร + วันที่คุ้มครองประกัน/พรบ. ทั้งหมด = วันนี้ */
                  ['obDocDate', 'obInsCoverStart', 'obInsCoverEnd', 'obPrbCoverStart', 'obPrbCoverEnd'].forEach(function (id) {
                      var el = g(id);
                      if (el && !el.value) { el.value = todayStr; }
                  });
                  items.addRow();
              })();
  /* the entry points of the inline handlers and of the window.* functions */
  
  var EXPORTED = ["SalesDocPreview","SalesDocPrint","SalesDocSaved","SalesDocFinance","SalesDocValidate","SalesDocCustomer","SalesDocPager","SalesDocSearch","SalesDocRef","SalesDocItems","SalesDocAttach","SalesDocModal","SalesDocPayModal"];

  /* "the document has been parsed": DOMContentLoaded handlers in the order they were registered, then "load" */
  readyState = 'interactive';
  runQueue(readyQueue, 'DOMContentLoaded');
  readyState = 'complete';
  tmo(function () { runQueue(loadQueue, 'load'); }, 0);

  return function destroy() {
    destroyed = true;
    disposers.splice(0).forEach(function (d) { d(); });
    timers.splice(0).forEach(function (h) { clearTimeout(h); });
    observers.splice(0).forEach(function (o) { o.disconnect(); });
    rt.destroy();
    EXPORTED.forEach(function (n) { try { delete window[n]; } catch (e) { window[n] = undefined; } });
  };
}

/** what the host has to load / start for this form (the Java head: attach_file_types.js, drag_scroll.js) */
export const SALES_DOC_OB_NEEDS = { attachFileTypes: true, dragScroll: ".qm-tbox" };
